function render(frame) {
  // Phase timings
  const cardInDelay = 4;
  const cardStagger = 6;
  const barFillStart = 28;
  const triplingStart = 75;
  const triplingEnd = 165;

  cards.forEach((c, i) => {
    // Card entrance
    const enter = staggeredSpring(frame, FPS, i, cardInDelay, cardStagger, 'SNAPPY');
    const ty = interpolate(enter, [0, 1], [base * 0.04, 0]);
    const drift = ambientDrift(frame, 1.5, 90, i + 1);
    c.card.style.opacity = enter;
    c.card.style.transform = `translateY(${ty + drift}px)`;

    // Subscribers bar fills to a baseline (33% width — representing subs level)
    const subsLocal = frame - (barFillStart + i * 4);
    const subsFill = interpolate(subsLocal, [0, 24], [0, 33], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    c.subsBar.style.width = subsFill + '%';

    // Views bar — starts at same level as subs, then triples
    const viewsLocal = frame - (barFillStart + 10 + i * 4);
    const initialFill = interpolate(viewsLocal, [0, 24], [0, 33], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

    // Tripling phase
    const tripleLocal = frame - (triplingStart + i * 6);
    const tripleProgress = interpolate(tripleLocal, [0, 60], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    // ease
    const eased = tripleProgress < 0.5
      ? 2 * tripleProgress * tripleProgress
      : 1 - Math.pow(-2 * tripleProgress + 2, 2) / 2;

    const finalFill = 33 + (66 * eased); // 33% -> 99%
    const currentFill = Math.max(initialFill, finalFill > initialFill ? finalFill : initialFill);
    c.viewsBar.style.width = Math.min(currentFill, 99) + '%';

    // Animate views number from start to end
    const currentViews = c.data.viewsStart + (c.data.viewsEnd - c.data.viewsStart) * eased;
    c.viewsNum.textContent = formatNum(currentViews);

    // Light pulse on views number during tripling
    const pulse = 1 + Math.sin(tripleProgress * Math.PI) * 0.04;
    c.viewsNum.style.transform = `scale(${pulse})`;

    // Dots fill in as tripling progresses
    c.dots.forEach((dot, d) => {
      const dotThreshold = (d + 1) / 3;
      const filled = eased >= dotThreshold - 0.05;
      const dotProgress = interpolate(eased, [dotThreshold - 0.1, dotThreshold], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
      if (filled) {
        dot.style.background = C.orange;
        dot.style.borderColor = C.orange;
        dot.style.transform = `scale(${1 + dotProgress * 0.1 * Math.sin(dotProgress * Math.PI)})`;
      } else {
        dot.style.background = C.bg;
        dot.style.borderColor = C.border;
        dot.style.transform = `scale(1)`;
      }
    });

    // Arrow appears during tripling
    const arrowOp = interpolate(tripleLocal, [0, 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    const arrowDrift = ambientDrift(frame, 4, 40, i + 5);
    c.arrow.style.opacity = arrowOp;
    c.arrow.style.transform = `translateY(${arrowDrift}px)`;
  });
}
